"""Human-authored semantic consolidation after reading all notes and passages.
Only locator expansion, serialization and coverage checking are automated.
"""
from pathlib import Path
import csv,json,re
from datetime import datetime,timezone
ROOT=Path(__file__).resolve().parents[4]
OUT=Path(__file__).resolve().parents[1]
PK='MPL_36_053-085+39'
FILE=f'pro/{PK}_transcription.tex'
PAGES=json.loads((ROOT/'work/pages.json').read_text())
src=(ROOT/'sources/texts'/FILE).read_text().splitlines()
entries=json.loads((ROOT/f'work/{PK}/entries.json').read_text())
items=[]; verdicts=[]
def loc(c,s,a=None,b=None):
 p=next(p for p in PAGES if p['file']==FILE and int(p['cote'])==c and int(p['scan'])==s)
 return {'file':FILE,'cote':c,'scan':s,'start':a or p['start'],'end':b or p['end']}
def add(n,ns,title,kind,locations,quote,statement,reconstruction,check,reason,verdict='kept'):
 id=f'SA13-{n}'
 ls=[loc(*x) for x in locations]
 items.append(dict(id=id,sources=[f'{PK}#{x}' for x in ns],kind=kind,cote=sorted(set(l['cote'] for l in ls)),scans=[f"{l['cote']}:{l['scan']:03d}" for l in ls],lines=ls,his_words=quote,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason,title=title))
 for j,x in enumerate(ns):
  verdicts.append(dict(entry_id=f'{PK}#{x}',item_id=id,verdict=verdict if j==0 else 'merged',reason=reason if j==0 else f'Merged with {id}: {reason}'))

INV='Let S be a strictly henselian trait with residue field k of characteristic exponent p, generic field K, and inertia I=Gal(Kbar/K). Let f:X→S be projective, regular and satisfy f_*O_X=O_S. Write X_0=Σd_iD_i, d=gcd(d_i), Δ=⊕Z D_i, Γ=Δ/Z X_0, and w:Γ→NS(X_0), where NS means the image of Pic(X_0) in the geometric Néron–Severi group. '
FORM='For a commutative ring k, let A_n⊂k[[t_1,…,t_n]] be unital subrings containing coordinates and constants A_0 and closed under permitted continuous substitution (input constants nilpotent). Let H mean closure under inverses of formal coordinate automorphisms, and D closure under all Hasse divided derivatives. '

add(400,[1],'Reynolds operators and the meaning of reductive','unproved claim',[(36,53,5,15),(36,55,64,82)],'the definition of ``reductive''','For a linearly reductive affine algebraic group over a field, each rational representation has a natural invariant projection E; E(rx)=rE(x) for invariant r. The typed text also begins an affine categorical-quotient theorem.','The modern term linearly reductive is a conditional identification of the missing source definition; modern reductive in positive characteristic is not substituted.','agrees','The note accurately distinguishes the missing definition/lemma from the Reynolds identity whose proof is written. This is reused typescript, not evidence of Grothendieck authorship.')
add(401,[2],'Affine quotient, proper action and stabilizers','unproved claim',[(36,59,180,188)],'cf. Iwahori [\\quad]','In the missing preceding geometric-quotient setup, the typescript compares affineness of the quotient morphism with properness of the action when stabilizers are finite, and says characteristic-zero stabilizers of an affine quotient are reductive.','The notation σ is the source’s action notation; whether properness refers to the action graph G×X→X×X must be recovered from its definition.','agrees','The two assertions and blank citation occur verbatim, but preceding hypotheses are absent. Do not make them unrestricted theorems or assign the typed authorship.')
add(402,[3],'Flat versus smooth equivalence relations','self-flagged step',[(36,57,126,139)],'Is \\uuline{flat} enough??','For a noetherian equivalence relation R⇉X with a geometric quotient Y and smooth projection, the margin asks whether the torsor/effectivity conclusion still follows with only flat projection.','One must specify sheaf quotient and scheme-theoretic equality R=X×_Y X; neither is supplied by equality of geometric orbits alone.','agrees','The boxed sentence is a genuine question attached to Proposition 0.9, not a proof of the flat version.')
add(403,[4],'Free action: smoothness and the orbit ideal','self-flagged step',[(36,57,132,155)],'ambiguous','The typed assertion is that a free action on algebraic schemes with geometric quotient is a principal bundle. Grothendieck’s annotations demand G smooth/k and flag the ideal used to identify the orbit local ring with O_{G,e}.','Scheme-theoretic freeness and the geometric quotient definition are required for a modern torsor statement.','agrees','The annotation identifies a proof vulnerability, not an exhibited counterexample; the note preserves that limitation.')
add(404,[5],'Algebraicity of a free-action quotient','conjecture',[(36,57,155,155)],'It seems very likely','The reused source hopes that algebraicity of Y follows from a free action on an algebraic X and an appropriate geometric quotient, without assuming Y algebraic.','The ambient category of Y is unstated; algebraic spaces, arbitrary locally ringed spaces and schemes must be distinguished.','agrees','This is a typed footnote expectation of unestablished authorship; no theorem follows from the word geometric alone.')
add(405,[6],'Biextensions with vanishing sheaf Hom','unproved claim',[(36,54,21,39)],'est discrète','On a topos, for abelian sheaves A,B,C with internal Hom(A,C)=0, biextensions have no nontrivial automorphisms and their classes identify with Hom(B,internal Ext¹(A,C)). Further identifications with rigidified C-torsors need the additional reduced-function-Hom/base-change assumptions in the lower diagram.','The word reduced in the function condition is not legible on the page and is not adopted as its reading; it describes what a nonvacuous geometric version would need.','agrees','The note correctly separates group-Hom from the ambiguous fct/ens condition and the sheaf/global comparison.')
add(406,[7],'Transposition and additivity of rigidified torsors','unproved claim',[(36,54,46,55)],'Les conditions a) et c) ensemble signifient','Under the torsor/Ext identifications of this page, a torsor rigidified along e_A×B whose B-parameter lies in Ext¹(A,C) induces an additive transposed parameter A→R¹q_*C_B.','The missing previous subsection hypotheses are retained as a condition; rigidification alone is not asserted to force a biextension.','agrees','The margin states this implication without a proof. The note accurately singles it out; the later claim of birigidifiability also uses the additive zero parameter, not rigidifiability alone.')
add(407,[8],'Birigidified torsors as biextensions','unproved claim',[(36,54,52,57),(36,56,88,94)],'dans des cas importants','For the geometric groups under consideration, the forgetful functor from biextensions to birigidified torsors is fully faithful; it is an equivalence only in stated special cases, which the next page explicitly assumes for A×A.','For abelian schemes and C=G_m, the theorem of the cube provides the standard special case; this is not a universal claim for abelian sheaves.','agrees','The box is an explicit hypothesis. The earlier note correctly refuses to absorb it into the definition of bitorsor.')
add(408,[9,10],'Quadratic pullback: sign and cross terms','reading question',[(36,56,94,120)],r'\varphi(u+v)-\varphi(u-v)=2(\varphi(u)+\varphi(v))','For pullback on NS of abelian schemes, the quadratic identity should have a plus between the two left terms; in particular [n]* acts by n². The literal minus identity forces 2φ(u)=0 at v=0 and is incompatible with a nonzero free NS group.','The plus identity is the mathematical candidate, not an emendation of the transcription; expanding pullback on biextensions accounts for the cross terms.','agrees','Both notes concern the same quadratic step. Their elementary sign test is sound; “évident” supplies only a sketch, and the written direction of Δ is separately flagged.')
add(409,[11,12],'The doubled Picard extension','unproved claim',[(36,58,161,173),(36,56,96,106)],'splitte canoniquement','If j and diagonal pullback provide a homomorphic lift s:NS→Pic with h∘s=2id, then the pullback of 0→Pic⁰→Pic→NS→0 along 2id has a canonical splitting; after inverting 2, s/2 splits the localized extension.','The kernel Pic⁰ and precise P/Pic source notation are reconstructed; the page’s subsequent assertion about j′hΔ* is unfinished. The localized consequence is the earlier run’s deduction.','agrees','The notes retain the unfinished calculation and condition the division-by-two consequence on existence and functoriality of s.')
add(410,[13],'Avoidance neighborhoods: intersection versus union','reading question',[(36,66,399,407)],r'\Delta_{U_1}\cap\cdots\cap\Delta_{U_n}=\Delta_{U_1\cap\cdots\cap U_n}','For normalized counting Haar measures of discrete H with H∩U={e}, Δ_U∩Δ_V=Δ_{U∪V}; the printed intersection in the subscript is false. In discrete Z, H=2Z, U={0,±2}, V={0,±3} disproves it.','This is an elementary test of reused typescript; union is a candidate reading, not a silent correction.','agrees','The note’s finite-set counterexample meets the displayed definition and directly diagnoses the formula.')
add(411,[14],'Compact generation in the Haar argument','unproved claim',[(36,68,480,490)],'engendré par un compact','In the reused Haar-measure setting, compact generation is used to propagate DK⊂KH to G=KH. The resulting cocompact-subgroup openness and covolume continuity need that hypothesis; the sheet explicitly says Proposition 6 fails without it.','An elementary modern counterexample to openness is a discrete infinitely generated group exhausted by finitely generated subgroups, when the exhaustion approximates the whole group but none has finite index (e.g. ⊕Z).','agrees','The recurrence and the warning are both present. The missing exercise number and preceding Proposition 6 are not invented.')
add(412,[15],'Lie groups and absence of small discrete subgroups','unproved claim',[(36,66,409,413)],'tout groupe de Lie satis-','The source defines condition (L): some identity neighborhood contains no nontrivial discrete subgroup. It begins to assert that every Lie group satisfies it, but the final word is cut off.','The completed modern statement follows from the no-small-subgroups property of finite-dimensional Lie groups. This completion is expressly editorial.','agrees','The note correctly records an interrupted source statement, not a fully transcribed theorem.')
add(413,[16],'Limits of Haar measures and covolume continuity','unpursued implication',[(36,70,547,565),(36,72,615,627),(36,66,399,407)],'ouf ! Vive les directed sets !','For locally compact G, a nonzero vague limit of Haar measures of closed subgroups is Haar on its support, using hypocontinuity and support nets. The reused text also proves continuity of covolume v on T°(g), compactness of uniformly discrete subgroups D_U, and local compactness of normalized discrete measures.','The definitions of T°,v and the initial compact slice are partly outside these retained leaves; they are not generalized beyond their source setting.','agrees','The note correctly separates different limit arguments; the support proof is complete here but the covolume proof continues off-page.')
add(414,[17],'Finite invariant-cycle defect sequence','unproved claim',[(36,61,202,234),(36,62,241,252)],r'\operatorname{Ker}w_n',INV+'For n prime to p, or dᵗ prime to p, or k perfect, the page asserts 0→Γ[n]→H¹(X,μ_n)→H¹(X_Kbar,μ_n)^I→ker(w⊗Z/n)→0. Here dᵗ is the index of X_K.','For n divisible by p, flat cohomology is required by the Kummer construction; the manuscript does not label a topology. Later handwritten proofs establish steps for n prime to p and index one, and do not by themselves prove every amended case.','agrees','The exact sequence, amended alternatives and explicit attribution to Raynaud are present. Its novelty is not inferred from the earlier project’s conjecture label.')
add(415,[18],'The vertical divisor quotient','reading question',[(36,61,214,220),(36,65,385,391),(36,69,508,508)],r'\Gamma\simeq/\underline Z\cdot X_0',INV+'The divisor-class kernel Pic(X)→Pic(X_K) is Γ=Δ/Z X_0; for regular X its torsion is cyclic of order d.','The missing numerator on scan61 is supplied only in the modern statement, from explicit later manuscript definitions; no text is changed.','agrees','The note identifies a real missing numerator and uses the internally explicit formula on65 and69.')
add(416,[19,20],'Radicial multiplicities and the index shortcut','unproved claim',[(36,61,228,231)],r'd^t=p^h d',INV+'The index is stated as dᵗ=gcd_i(μ_i d_i), where μ_i is the radicial multiplicity of D_i/k. The inserted further equality dᵗ=d·gcd_i μ_i needs an additional geometric relation; it is not a general gcd identity.','The earlier run’s integer example (d_i)=(2,3),(μ_i)=(1,2) tests only arithmetic, not realizability by a regular family.','agrees','The note and test accurately expose the unsupported factoring of a gcd without claiming a geometric counterexample.')
add(417,[21],'The finite cyclic kernel R','unproved claim',[(36,61,234,234),(36,62,241,241),(36,71,585,590)],'noyau est contenu dans le sous-groupe de torsion',INV+'The page asserts R=ker(w)⊂tors Γ≅Z/d, hence R is cyclic of some order e dividing d. It separately asks whether R equals all tors Γ.','We use e for this order, reserving index dᵗ for the different quantity called d′ in the handwritten draft.','agrees','The note correctly refuses to replace a subgroup by the whole cyclic torsion group.')
add(418,[22,23],'The ℓ-primary tensor-order discrepancy','reading question',[(36,62,261,269),(36,71,585,586)],r'\underline Z/\ell\underline Z\text{ si }\ell\mid d\prime','If R≅Z/e, then R⊗Z_ℓ≅Z_ℓ/eZ_ℓ≅Z/ℓ^{v_ℓ(e)}. The page’s case Z/ℓ when ℓ|e is false if v_ℓ(e)>1; at scan71 it also substitutes d for the unproved kernel order.','The corrected formula is elementary algebra, not an ink decision.','agrees','The earlier run’s example e=ℓ² correctly diagnoses the literal formula and does not refute the geometric invariant-cycle theorem.')
add(419,[24],'The Brauer obstruction at arbitrary n','unproved claim',[(36,63,287,306)],r'p^m\theta(n)=0',INV+'For arbitrary n the page adds 0→ker w_n→Q(n)→θ(n)→0, with θ(n)⊂Br(K)[n] in the relative Brauer kernel, annihilated by gcd(n,dᵗ), hence by the p-primary part of dᵗ.','Use flat Kummer cohomology for arbitrary n. The precise injection and compatibility require the Picard–Brauer construction; only its statement is written here.','agrees','The note accurately records the extra obstruction and marks the circled injection as attention rather than a specified error.')
add(420,[25],'Bounded exponent and inverse-limit transition maps','idea of the earlier run',[(36,63,304,308)],r'\varprojlim_\nu\theta(\ell^\nu)=0','Uniform bounded exponent does not by itself force an inverse limit to vanish: the constant system Z/p with identity maps has limit Z/p. For subgroups of a fixed bounded p-primary Brauer group with transitions multiplication by p, the limit is zero.','This tests the abstract inference. For the manuscript, the Kummer coefficient map induces multiplication by ℓ on the Brauer n-torsion obstruction, a compatibility that must be checked.','agrees','The note’s counterexample and conditional repair are correct; this is not a counterexample to the actual compatible Kummer system.')
add(421,[26],'The revised ℓ-adic theorem','unproved claim',[(36,62,256,279),(36,63,306,308)],'à condition de supposer $\\ell\\neq p$',INV+'The live statement asserts 0→H¹(X,Z_ℓ(1))→H¹(X_Kbar,Z_ℓ(1))^I→R⊗Z_ℓ→0 for every prime; the untwisted version is restricted to ℓ≠p. The cokernel is finite and zero for almost all ℓ.','For ℓ=p interpret the twist via the flat Kummer inverse system, not a locally constant étale sheaf; the manuscript’s extension beyond prime-to-p depends on the Brauer-transition argument.','agrees','The note correctly reads deleted restrictions as a proposed enlargement and preserves the remaining restriction on untwisted coefficients.')
add(422,[27,28],'The Kummer cover and its index','unproved claim',[(36,63,310,321),(36,64,328,337)],'unique à isomorphisme près',INV+'Writing dᵗ=p^r a with (a,p)=1, the corollary asserts a connected ramified Kummer S′/S of group μ_a and compatible finite étale X′→X, generically cartesian, removing the prime-to-p invariant-cycle defect.','Its written conclusion d(X′/S′)=p^r uses d rather than dᵗ and needs qualification when radicial multiplicities are nontrivial. The upper cover is not stated principal after cancellation.','agrees','The notes accurately retain connectedness, uniqueness as unproved, and the d/dᵗ discrepancy rather than normalizing it.')
add(423,[29],'Degree-one cycles in the Picard–Brauer argument','unproved claim',[(36,65,344,391)],'un 0-cycle de degré 1','For a proper regular X over a strictly henselian trait with f_*O_X=O_S and generic index one, the Picard–Brauer obstruction for X_K is zero, Γ is torsion-free, and prime-to-p Kummer comparison reduces invariant cycles to the map Pic(X)[n]→Pic(X_K)[n].','A zero-cycle of degree one is sufficient via restriction/corestriction; no rational point is being silently required.','agrees','The note correctly states that index one removes a Brauer obstruction as well as giving gcd d_i=1.')
add(424,[30],'Lifting roots of line bundles','self-flagged step',[(36,67,421,441)],'du moins si $S$ complet','For a proper X over a complete strictly henselian trait and n invertible, the proof needs Pic(X)/n→Pic(X_0)/n to be injective: an n-th root on the special fiber should lift. Pic⁰(X_0)(k) must also be n-divisible in the comparison with NS.','The n prime-to-p restriction comes from the surrounding special-case proof; p-power roots are not claimed to lift by this argument.','agrees','The margin defers the lemma and cites an uncertain FGA/SGA Picard reference, exactly as the note records.')
add(425,[31],'Withdrawn injectivity proof routes','withdrawn in the same text',[(36,67,452,474),(36,69,508,535)],'cf plus bas une démonstration','In the index-one case the live goal Γ→NS(X_0) injective is unchanged. Two draft proof routes are deleted; the surviving passage gives the degree argument and appeals to Raynaud’s Picard specialization theorem.','The deleted curve/intersection sketch is evidence of revision, not an independent proof and not a retraction of the claim.','agrees','The note tracks both abandoned places and the live external appeal correctly.')
add(426,[32],'Torsion of a quotient versus quotient of torsion','withdrawn in the same text',[(36,65,363,367),(36,67,466,474),(36,69,500,506)],r'{}_n\delta/{}_n\delta\prime','For 0→δ′→δ→δ″→0, the n-torsion long exact sequence includes δ″[n]→δ′/nδ′. Thus δ[n]/δ′[n] is only the image in δ″[n], not generally all δ″[n].','The correction from the crossed δ″[n] to δ[n]/δ′[n] is already Grothendieck’s; no further emendation is made.','agrees','The note identifies an actual correction and its exact connecting morphism.')
add(427,[33],'Index divisibility and requested curve proof','self-flagged step',[(36,69,508,535)],'donner \\unsure{corollaire}','For regular proper X/S with special fiber Σd_iD_i, the closure of a generic closed point has degree Σd_i(Z·D_i), so gcd d_i divides every zero-cycle degree. The margin asks about weakening regularity and requests a direct relative-curve proof of the injectivity consequence.','Local factoriality suffices for the displayed Cartier intersections with a finite horizontal closure, but this does not replace regularity in all subsequent steps.','agrees','The note is careful about the ambiguous est/sans and subsist-il/suffit-il reading and does not invent a weaker theorem.')
add(428,[34,58],'Does the invariant-cycle kernel equal all vertical torsion?','self-flagged step',[(36,71,585,590),(36,61,234,234)],'demander Raynaud si $\\operatorname{Ker}$ est donc $\\mathbb Z/d\\mathbb Z$',INV+'Does ker(Γ→NS(X_0)) equal tors Γ? The page asserts prime-to-p containment but asks about the entire group.','Raynaud’s equality E(S)∩P^τ(S)=tors E(S) does not automatically imply equality with a kernel using Pic⁰ rather than Pic^τ; in relative dimension one, NS of a proper curve is detected by multidegrees and the equality does follow under the local-factorial hypotheses.','agrees','Both entries concern the same unresolved question and correctly distinguish the full NS quotient from numerical/torsion equivalence.')
add(429,[35],'Removing resolution from the finite-kernel argument','self-flagged step',[(36,71,588,590)],'même sans résolution','The proof first qualifies finiteness/torsion of ker(Γ→NS(X_0)) by resolution of singularities, then proposes removing that qualification by Raynaud, apparently Proposition 7(ii).','The short announcement numbering remains uncertain; the full 1970 Theorem 6.4.1 supplies the numerical/P^τ finiteness ingredient without resolution.','agrees','This is a marginal proposal to use an external result, not a proof performed on the page.')
add(430,[36],'Two distinct quantities written d′','reading question',[(36,62,241,266),(36,69,508,508),(36,71,570,575)],'pgcd des deg. des 0-cycles','The typed draft uses d′=|ker w|; the handwritten draft uses d′=index(X_K). These quantities need not agree and must receive different names in a modern account.','This dossier writes e=|ker w| and dᵗ=index; the source symbols are preserved in quotes.','agrees','The note’s warning is directly confirmed at all three occurrences.')
add(431,[37],'Local factoriality: a specific weakening','unpursued implication',[(36,65,385,389),(36,83,909,923)],'il suffirait: anneaux locaux factoriels','Local factoriality gives extension of generic line bundles by Cartier divisors and underlies the curve component-group finiteness assertion. It does not by itself discharge every use of regularity in the earlier theorem.','Only the visible local extension/intersection step is weakened.','agrees','The note correctly limits the scope of the parenthetical weakening.')
add(432,[38,49,97],'Arithmetic orthogonality: statement, scope and print comparison','unproved claim',[(36,73,631,631),(36,74,638,680),(36,75,684,705),(36,76,709,723),(36,77,736,744),(36,79,758,784)],'Th. d’orthogonalité (partiel!)','Let A be noetherian, separated and J-adically complete, X=Spec A, Y=V(J), U=X\Y. Let G,G′ be flat separated commutative finite-type X-groups, abelian over U, with divisorial correspondence ξ; let ℓ be invertible, S⊂G_Y flat with all S[ℓ^ν] finite and T⊂G′_Y a torus. The lifted Tate submodules pair to zero over U. Over a henselian trait the Néron corollary says fixed and dual toric parts are orthogonal.','No regularity is assumed on A. The full published orthogonal-complement equality over a henselian trait is stronger than this draft’s inclusion; SGA7 IX 2.6(a) identifies the arithmetic proof of the inclusion, not all of the general-base statement.','agrees','The earlier notes correctly qualify the Hua paraphrase, distinguish vanishing from perfectness, and identify the printed arithmetic method. The initial theorem remains a sketch at its full adic-base generality.')
add(433,[39],'Finite étale lifts of torsion subgroups','unproved claim',[(36,74,647,667)],'les ${}_{\\ell^\\nu}G$ sont étales','For a flat finitely presented commutative group G and an invertible integer ℓ, the ℓ^ν-kernel is étale; a finite étale subgroup on Y lifts uniquely through a henselian pair (A,J) as a finite étale part of that kernel, compatibly in ν.','The noetherian hypothesis converts finite type to finite presentation. The lifting statement uses the finite-part theorem for separated étale schemes, not just equivalence of abstract finite étale categories.','agrees','The note correctly identifies the extra proof needed after lisses is replaced by plats.')
add(434,[40,41],'Frobenius spectral separation','unpursued implication',[(36,75,701,705),(36,76,709,718)],'$q^2\\,\\mathrm{id}$','Over a finite field F_q and ℓ≠p, any Galois-equivariant pairing T_ℓ(S)×T_ℓ(T)→Z_ℓ(1), for finite-type commutative S and multiplicative-type T, is zero. After removing finite/unipotent parts and splitting tori, source eigenvalue absolute values are q² or q^{3/2}, whereas the target has q.','The earlier run’s coprime-polynomial intertwiner proof shows semisimplicity is unnecessary. Finite-field Tate modules are finitely generated free over Z_ℓ and the target torsion-free, so rational vanishing implies integral vanishing.','agrees','The actual weight calculation and its group-theoretic reductions appear on the pages; the abstract proof criterion is labelled as the earlier run’s formulation.')
add(435,[42],'Detection by traits and finite-field specializations','unproved claim',[(36,74,679,680),(36,75,684,699)],'dominant par un anneau de val. discret','The proof reduces a pairing on U to traits meeting Y, then to completions with finite residue field and one-dimensional specializations, preserving the lifted Tate subgroups.','Existence and detection depend on noetherian adic/Jacobson geometry and normalization of a one-dimensional complete domain; they are not assertions that the original base is normal.','agrees','The note correctly isolates the nontrivial geometric bridge that is only compressed into the draft.')
add(436,[43,44],'A single model for all torsion levels','unproved claim',[(36,76,721,731),(36,77,736,744)],'Mais les ${}_{\\ell^\\nu}S_i$ sont encore finis','The proof spreads a group filtration and all relevant data to one finite-type Z-model. To retain finiteness of S_i[ℓ^ν] simultaneously, it suffices to descend a semiabelian/unipotent filtration and establish finite multiplication by ℓ on that model, then iterate.','The one-finite-map argument is an earlier-run proposed completion; descent separately for each ν would be insufficient.','agrees','The notes identify a real quantifier issue and a conditional route resolving it, without pretending that the draft wrote the verification.')
add(437,[45],'Cancelled strict-henselian orthogonality draft','withdrawn in the same text',[(36,81,803,861),(36,77,736,744)],'Pour $i$ grand, ils sont bijectifs.','The entire strict-henselian theorem and preliminary descent proof on scan81 are deleted; the live general-base proof is on74–77.','Sheet order gives no composition chronology. The stabilization remark in a deleted proof is not independent verification.','agrees','The note accurately marks the whole block cancelled and cites the live comparison.')
add(438,[46],'Polarized and two-variable corollaries','unproved claim',[(36,79,767,784)],'les deux corollaires sont à priori équivalents','Orthogonality for every divisor correspondence A×B and orthogonality for every polarization of an abelian variety are equivalent. One uses a product A×B and sufficiently ample diagonal polarization plus off-diagonal correspondence; bilinearity isolates the cross pairing.','A rational/isogeny argument suffices because the integral target Z_ℓ(1) is torsion-free. Denominators are not silently assumed invertible in Z_ℓ.','agrees','The page leaves this equivalence to the reader, exactly as the note says.')
add(439,[47,48],'Finite torsion pairings need not vanish','unpursued implication',[(36,79,786,790),(36,80,794,799)],'quitte à agrandir $K$ en $K^{\\prime}$','Even when the Tate-module fixed/toric pairing is zero, a nonzero finite toric torsion point is detected by a torsion point of the dual abelian variety after a finite extension K′/K. Such a point need not extend to a compatible rational division tower.','The final A′(K) is understood only conditionally as renamed K′; the source keeps K. This does not prove nonvanishing over the original field.','agrees','The notes correctly distinguish inverse limits from finite levels and identify the unupdated field label.')
add(440,[50],'Curve component groups as kernel and cokernel','unpursued implication',[(36,83,877,912)],'\\Phi=\\operatorname{Ker}u','For a cohomologically flat proper relative curve over a trait with local factoriality, E=Z^r/Z(d_i), E*=ker[Z^r→Z,(n_i)↦Σd_iδ_i n_i], and u is induced by the intersection matrix normalized in row j by δ_j. The source gives Φ=ker u≅Z/d and Ψ=coker u.','The general Picard functors P,Q refer back to preceding work. The invariant-cycle group R is a different kernel; it is not Ψ.','agrees','The note correctly prevents a kernel–cokernel conflation and identifies the visible relationship with Γ.')
add(441,[51],'The missing u in the intersection formula','reading question',[(36,83,898,912),(36,84,943,958)],r'(\beta\circ\alpha)((n_i)_i)','The map whose coordinates are Σ_i n_i(C_i,C_j)/δ_j is βuα:Z^r→Z^r; βα is not defined for α:Z^r→E and β:E*→Z^r.','The modern expression inserts u using the explicit later formula; it is a reading candidate rather than a change to scan83.','agrees','The note’s type check and both source endpoints agree.')
add(442,[52],'Néron-model hypothesis revisions','withdrawn in the same text',[(36,83,914,923)],'Si de plus','In the relative-curve setting, local factoriality is retained for finiteness of Ψ; the additional hypothesis residue field perfect or dᵗ prime to p is assigned to the Néron-model assertion for Q′. If dᵗ=1, Φ=0 and representability is asserted.','The initial setting and geometric irreducibility requirements must be recovered from the Picard construction; Raynaud’s theorem provides the exact published version.','agrees','The note reads the deleted and reinserted hypotheses correctly and does not flatten their different roles.')
add(443,[53],'Weighted transpose and intersection symmetry','unpursued implication',[(36,84,927,958)],r'\sum\delta_i n_i n\prime_i','The pairing on Z^r with diagonal weights δ_i makes λ and μ transposes; the induced pairing E×E*→Z satisfies (x,u(y))=(y,u(x)) because intersection numbers are symmetric. This does not imply unimodularity when δ_i≠1.','Only elementary lattice algebra is claimed; the cancelled parfait is not restored.','agrees','The two calculations are explicitly separate in the draft and the earlier note preserves that distinction.')
add(444,[54,55],'The discriminant pairing and a rank-one test','idea of the earlier run',[(36,83,898,912),(36,84,960,965)],'une \\uline{autodualité} canonique','For free finite-rank E, E*=Hom(E,Z), and an injective self-adjoint finite-index u:E→E*, the pairing b(x̄,ȳ)=y(u_Q^{-1}x) mod Z on coker u is well-defined, symmetric and perfect. For d=(1,1), weights1 and intersection matrix [[−m,m],[m,−m]], u=−m in the natural quotient/dual bases, so b(a,b)=−ab/m.','This is the earlier run’s explicit algebraic construction and sign test, not a claim that every matrix is geometrically realizable or that the geometric comparison is proved by symmetry alone.','agrees','The notes’ representative, symmetry and perfectness arguments are valid under the stated integral hypotheses.')
add(445,[56],'Residue weights and the integral dual lattice','idea of the earlier run',[(36,84,927,965)],'Si les $\\delta_i$ sont tous $1$','When some residue weights δ_i are nonunits in Z, the weighted E–E* pairing may have finite index in the true dual lattice. A discriminant formula using only u then needs an additional comparison before it describes a perfect pairing on Ψ.','This is a proposed comparison of finite index defects, not a theorem that the geometric pairing fails or a computed universal correction group.','agrees','The note correctly limits the simple formula to the unweighted perfect-duality hypotheses on the page.')
add(446,[57,59],'Geometric obstruction and the intersection pairing','unproved claim',[(36,84,960,965)],'exprime l’obstruction','When δ_i=1 and d=1 in the curve setting, the draft identifies the canonical discriminant autoduality on Ψ with the obstruction to extending the generic Poincaré biextension to the Néron models.','This is a geometric comparison, beyond the proved lattice symmetry. Later Jacobian comparison theorems have explicit regular-model and rational-point hypotheses.','agrees','The notes appropriately separate construction of the finite pairing from its identification with Grothendieck’s biextension obstruction.')
add(447,[60],'Two axiom drafts and changing labels','reading question',[(39,3,984,1034),(39,4,1040,1076),(39,10,1179,1211),(39,12,1252,1261),(39,15,1340,1353),(39,16,1363,1365)],'k anneau commutatif','The first draft is over a field; the second is over a commutative ring. Inverse closure is f in the first and d/e in the second, while the later f is integral quotient closure. Comparisons must use the content of axioms.','We use H,D and integral-quotient closure as editorial names. The first draft’s minimal a,b,d family at line1027 also appears to require the prime ring, not its fraction field, unless c is retained.','agrees','The notes accurately warn about relabeling and changed base. The extra minimal-family arithmetic issue is listed separately for scan checking.')
add(448,[61],'The target of the first unit axiom','reading question',[(39,3,1011,1031)],r'\frac1f\in\unsure{S_n|\mathcal A_n}','Unit closure in A_n is equivalent to locality of A_n with local inclusion into the local formal-series ring, provided A_n contains the induced constant prime field under the first draft’s field hypotheses. Merely 1/f∈S_n is tautological.','The stronger target A_n is suggested by c′ and the examples, not selected as the ink reading.','agrees','The note correctly identifies a materially different pair of possible readings.')
add(449,[62],'Does individual henselianity imply inverse closure?','self-flagged step',[(39,4,1054,1067)],'il ne semble pas','For a family of local subrings A_n⊂k[[t]] satisfying the first draft’s ring, coordinate, substitution and unit axioms, does henselianity of every A_n imply H? The manuscript withdraws an asserted equivalence and doubts the converse.','Ordinary henselianity solves polynomial systems; H asks for inversion of maps whose coordinates may be arbitrary selected formal series. A precise family-level converse is separate.','agrees','The note correctly distinguishes the questioned converse from the forward implicit/Hensel conclusion.')
add(450,[63],'The minimal algebraic-power-series family','unproved claim',[(39,4,1063,1072)],r'B_n=P\{t_1,\ldots,t_n\}','Over the prime field P⊂k, the henselizations P[t]_(t)^h embedded in k[[t]] form a substitution- and inverse-closed family of algebraic power series. They provide the minimal henselian family of the first draft.','The example proves neither the general converse nor the crossed inverse-coordinate argument for arbitrary A_n.','agrees','The note correctly limits the claim to this explicit family and keeps the doubtful vicié/inutile annotation unresolved.')
add(451,[64],'Autonomous and time-dependent flow closure','unproved claim',[(39,5,1081,1101)],'la variable temps devenant variable spatiale','In characteristic zero, assume the A-family supports smooth formal coordinates and flow closure for its autonomous vector fields. A time-dependent field ξ(t,x) becomes ∂_t+ξ on the product; its flow at initial t=0 yields the required time-dependent solution. Conversely constant-in-time fields are a special case.','This reconstruction spells out the source’s one-sentence reduction and uses only allowed product and zero substitutions.','agrees','The note accurately asks for closure checks rather than treating integration as a consequence of henselianity alone.')
add(452,[65],'Primitives and elementary transcendental functions','unpursued implication',[(39,7,1122,1124),(39,8,1144,1145)],'stable par \\unsure{primitivation} canonique','In the characteristic-zero field setting with H and flow closure, A_1 contains zero-based primitives, log(1+t), exp(t), sine, cosine and tangent. These follow from the corresponding one- or two-dimensional differential equations and unit closure.','The cancelled copy at scan8 is not an additional proof. The algebraic henselization family alone does not contain exp(t).','agrees','The note correctly separates the integration stage from the earlier algebraic implicit-function stage.')
add(453,[66],'Baker–Campbell–Hausdorff laws in the chosen family','unproved claim',[(39,6,1105,1118)],'Cette dernière est une $\\mathcal A$-loi','For finite-dimensional Lie algebras over k_0 in characteristic zero, the draft asserts that the BCH formal group and induced homomorphisms carry A-structures when the family has the stated integration closure. It reduces through Ado to a formal matrix subgroup.','The missing closure of that subgroup is part of the unfinished construction; the classical ambient BCH theorem alone does not prove it for every A-family.','agrees','The note accurately reads a claimed consequence followed by an incomplete reduction.')
add(454,[67,68],'Pfaff integration in the chosen family','conjecture',[(39,7,1124,1139),(39,16,1363,1365),(39,17,1369,1371)],'On veut qu’on ait une réciproque','In characteristic zero, an involutive A-subbundle of rank p in the tangent bundle of a smooth formal A-space is required to admit an A-quotient foliation. The margin says this implies flow closure and is equivalent to it for p=1.','This is a desired closure axiom. Successive-flow charts are an earlier-run research proposal; no higher-rank closure theorem is proved on the page.','agrees','The notes correctly distinguish the added integral condition from a theorem deduced from logical or henselian axioms.')
add(455,[69],'Cancelled retraction/product formulation','withdrawn in the same text',[(39,8,1144,1174),(39,7,1129,1139),(39,16,1359,1365)],'Conditions équivalentes','The retraction/product criterion for a transversal to a formal foliation on scan8 is entirely cancelled. Live versions remain at scan7 and in the quotient discussion at16.','Their coordinate labels are not combined into a single surviving proof; cancelled valid ideas can remain evidence of reformulation.','agrees','The note describes the exact cancellation scope and comparisons correctly.')
add(456,[70],'Permitted formal substitutions','unpursued implication',[(39,10,1192,1203)],'les $f_i$ sont tels que $\\varepsilon(f_i)$ \\uline{nilpotent}',FORM+'Continuous substitutions require nilpotent input constants. Ring and constant closure allow evaluation of an arbitrary outer allowed series once the inner inputs are admissible; they do not allow substituting 1 for a formal variable.','This is formal-topological reconstruction of the margin and its later failure example.','agrees','The note correctly keeps inner and outer augmentation restrictions distinct.')
add(457,[71],'Free, projective and arbitrary finite modules','self-flagged step',[(39,11,1228,1244)],'projectifs de type fini?','The source constructs Spf(completed Sym_k(M_0⊗k)) for finite free A_0-modules and asks about finite projectives and finite modules. Projectives require compatible local/descent coordinates or idempotent splitting; arbitrary finite modules generally produce nonsmooth formal schemes.','The category in the passage is smooth formal A-spaces, so the latter extension requires enlarging its objects.','agrees','The note identifies two distinct extension questions and does not promote the doubtful margin to a proof.')
add(458,[72],'Transversal fiber products and implicit closure','unproved claim',[(39,11,1228,1239)],'dans le cas ``transversal''',FORM+'The draft asserts finite products and transversal fiber products before stating H. Finite products follow from coordinate closure; a transversal fiber product needs solutions of implicit equations in the chosen family or a definition admitting arbitrary such pullbacks.','Under H, a formal implicit-function chart supplies the missing construction; under polynomial-only axioms this is not automatic in a coordinate-defined category.','agrees','The earlier note correctly identifies the dependency and avoids equating Linc(k_0) with all smooth schemes.')
add(459,[73,74],'Invalid evaluation at one and the differential repair','withdrawn in the same text',[(39,12,1260,1282),(39,15,1341,1341)],'incorrect, 1 n’est pas nilp.!',FORM+'H yields f(t)^{-1}s∈A_{n+1} from (t,s)↦(t,f(t)s) when f(0)∈k*. Evaluating s=1 is invalid; D or explicit coefficient extraction gives f^{-1}∈A_n.','The differential repair is the earlier run’s explicit proof of the manuscript’s proposed remedy. The stronger ambient-unit conclusion uses D.','agrees','The note faithfully records his rejection and gives a valid coefficient-extraction replacement.')
add(460,[75,76,77],'Zariskian conclusion without reflection of all units','idea of the earlier run',[(39,12,1260,1282),(39,13,1294,1294)],'donc en fait $\\in k_0^*$',FORM+'H alone makes I_n=A_n∩(t) lie in Jac(A_n): invert (t,s)↦(t,(1+h(t))(1+s)−1) and set s=0. It does not make every k-unit in A_n invertible there. Counterexample: k=Q, A_n=Z+(t)Q[[t]], A_0=Z; H holds but 2^{-1} is absent.','The counterexample meets ring/coordinate/substitution/H axioms but fails D and is not a counterexample to the henselian-pair conclusion. The parenthetical unit reflection requires an extra hypothesis.','agrees','All three notes concern the same precise distinction and provide correct proofs/counterexample with its boundary.')
add(461,[78],'Henselian-pair factor lifting from H','idea of the earlier run',[(39,12,1285,1289),(39,13,1294,1316)],'le couple $(\\mathcal A_n,\\mu_n=\\mathfrak m_n\\cap \\mathcal A_n)$',FORM+'Assume A_n/I_n=A_0 via augmentation. Given a monic polynomial reducing to comaximal monic factors over A_0, center the coefficient multiplication map at those factors; its Sylvester matrix is invertible. H and permissible substitution lift the factors. Together with I_n⊂Jac(A_n), this proves the pair henselian.','This is the earlier run’s repaired proof; coprime means the ideals generated by the two monic factors sum to A_0[Z], not merely no common factor over a fraction field.','agrees','The resultant/Jacobian argument uses finite polynomial coefficient algebra and legal zero-constant substitutions, so it survives the rejected s=1 argument.')
add(462,[79],'Implicit functions by inverse coordinates','unpursued implication',[(39,13,1304,1316)],r'\varphi(t_1,\ldots,t_n,0)',FORM+'If P(t,z)∈A_{n+1}, P(0,0)=0 and ∂P/∂z(0,0) is a unit in k, the unique zero-constant formal solution z=F(t) lies in A_n, by inverting (t,z)↦(t,P(t,z)) and setting its last output to0.','For a polynomial root with nonzero constant ζ∈A_0, finite coefficient translation P(z+ζ) is allowed algebraically without claiming translation is a pointed formal morphism.','agrees','The note correctly contrasts the legal zero evaluation with the rejected unit proof.')
add(463,[80,81],'Faithful flatness: the meaning of d matters','self-flagged step',[(39,13,1317,1323),(39,15,1340,1342)],'est fid. plat sur $\\mathcal A_n$',FORM+'The margin asks if k[[t]] is faithfully flat over A_n when k is faithfully flat over A_0. If d means D alone, A_n=Q[t] is a counterexample to faithfulness: A_1/(1−t) is nonzero but becomes zero over Q[[t]]. If d includes H, this counterexample does not apply.','The letter ambiguity is retained. No general flatness theorem for all H-families is inferred from henselianity.','agrees','The note correctly limits its negative answer to the differential-only reading and leaves the stronger question open on the pages.')
add(464,[82,83],'Divided derivatives and characteristic zero','idea of the earlier run',[(39,15,1341,1342)],'en car. 0 c’est équivalent','Hasse derivative D_p extracts the coefficient of at^p in characteristic p, while the ordinary derivative kills it. In characteristic zero, equivalence of ordinary-derivative and Hasse-derivative closure requires factorial inverses in the coefficient algebra; Z[t,t²/2] is derivative-stable but D_2(t²/2)=1/2 is absent.','These are operator-level tests, not purported full A-family counterexamples. Under H plus D with k a characteristic-zero field, unit reflection can make A_0 contain Q, but characteristic zero alone does not.','agrees','The note’s examples correctly state their scope and identify the missing scalar-closure condition.')
add(465,[84],'Principal parts and differential operators','unproved claim',[(39,15,1341,1351)],'canoniques, fonctiorielles',FORM+'Under D and the coordinate/inverse closure needed for charts, finite principal parts, infinitesimal neighborhoods of smooth subobjects and finite-order differential operators should carry canonical A-structures, compatible with composition and transverse base change; the relative assertion is for submersive maps.','The quoted spelling is editorially normalized only in the statement. The source announces coordinate-independence without constructing it.','agrees','The note correctly preserves the enlargement from étale to submersif and identifies the missing functorial verification.')
add(466,[85],'Coefficient descent to A_0','unpursued implication',[(39,15,1341,1353)],r'\mathcal A_n\subset k_0[[t_1,\ldots,t_n]]',FORM+'Each coefficient of f∈A_n is the zero value of a Hasse derivative, hence belongs to A_0; therefore A_n⊂A_0[[t]]. The induced functor to formal A_0-schemes is then asserted.','The inclusion is proved by coefficient extraction; the global functorial construction remains a sketch. H alone does not imply it, as the family Z+(t)Q[[t]] shows.','agrees','The note correctly distinguishes differential coefficient descent from inverse closure.')
add(467,[86],'Induced substructures and the graph criterion','unproved claim',[(39,14,1328,1333)],'Cette $\\mathcal A_*$-structure est alors unique',FORM+'For a smooth formal subspace Y⊂X, an induced A-structure, when it exists, is unique if a transversal A-chart identifies Y formally with an A-space and H applies. A map is A-admissible exactly when its graph is an induced A-subspace.','Existence of a suitable chart over arbitrary k is a local/projective-module issue; the draft says immediate but does not prove it globally.','agrees','The note identifies the chosen-chart mechanism and the missing independence/existence verification.')
add(468,[87],'Smooth completion along a section','unproved claim',[(39,14,1336,1336)],'une constr. utilisant e)',FORM+'A scheme smooth over Spec O_A(X) along a section is asserted to acquire a functorial A-structure on the completion after base change to O(X), with section and projection A-morphisms and compatibility with base change.','Local étale coordinates plus H give the expected construction; gluing and projective tangent-module scope are not written out.','agrees','The note accurately records an announced construction and its required compatibilities.')
add(469,[88],'Quotient structure and its transversal source','reading question',[(39,16,1359,1361)],r'\unsure{X\prime|X}\to Y\prime',FORM+'For a smooth formal submersion p:X→Y, choose an A-transversal Y′⊂X with Y′≅Y. The quotient A-structure exists exactly when the composite X→Y≅Y′ is A-admissible, and is unique under H.','The source of that composite is mathematically X; X′ is retained as an alternative reading only.','agrees','The note correctly uses the displayed diagram to motivate but not decide the source label.')
add(470,[89],'Integral effectivity of formal equivalence relations','conjecture',[(39,16,1363,1365),(39,17,1369,1371)],'Condition intégrale',FORM+'The added integral condition demands that a smooth formal equivalence relation R⊂X×X carrying induced A-structure have a quotient carrying quotient A-structure. In characteristic zero the text heuristically relates this to integrating Pfaff systems.','This is an axiom proposed for the chosen family, not a conclusion from a,b,c,H,D; smoothness/submersive projection conditions belong to the formal quotient setting.','agrees','The note preserves the distinction between a desired effectivity property and an established consequence.')
add(471,[90,91,92,93,94,95,96],'Formal division and preparation in complete linear topology','unproved claim',[(39,19,1376,1419),(39,20,1424,1455)],'anneau linéairement topologique, séparé et complet','Let A be a commutative separated complete linearly topological ring, F=Σa_iZ^i, a_N a unit and a_0,…,a_{N−1} topologically nilpotent. Then A[[Z]]=A[Z]_{<N}⊕F A[[Z]], F is regular, and F=UP uniquely with U a unit and P monic degree N with topologically nilpotent lower coefficients.','The pages state unique division and regularity. Preparation factorization is the earlier run’s deduction. A complete proof reduces modulo open ideals, uses nilpotent I=(a_i:i<N), and the full unit series F mod I=Ubar Z^N. The final scalar α is a reading alarm. The finite perturbation inverse and compatibility by uniqueness fill explicit omissions; cancelled routes do not cancel the theorem.','agrees','The seven entries concern one theorem and its proof/reading/consequence. Their finite-filtration proof is valid, but the scalar replacement must not be treated as the literal general argument.')
add(472,[98],'Scope and unfinished-argument inventory','other',[(36,73,631,631),(36,62,269,269),(36,63,299,306),(39,6,1115,1118),(39,7,1124,1127),(39,16,1365,1365),(39,17,1369,1371)],'partiel!','The summary distinguishes attention marks, a partial theorem’s scope, unfinished BCH construction and proposed integral axioms. These refer to items432,453,454,470 rather than independent new conjectures.','This is the earlier run’s inventory, checked against the actual passages; repeated flags create no extra mathematical claims.','agrees','The source has exactly the quoted marks and ellipses, and the note does not mistake every mark for a refutation.')
add(473,[99],'Withdrawal inventory','other',[(36,67,455,469),(36,69,529,540),(36,81,803,861),(36,83,914,923),(39,4,1058,1067),(39,8,1144,1174),(39,19,1412,1420),(39,20,1424,1455)],'cqfd.','The summary lists cancelled proof routes and whole drafts alongside their live replacements. It creates no independent proof and does not retract the surviving claims.','This is a meta-level consolidation of items425,426,437,442,449,455,471.','agrees','Every listed cancelled block is marked deleted in the supplied transcription; the final preparation cqfd remains live.')
add(474,[100,101],'Headings, pagination and context comparison inventory','title, date or page count',[(36,60,194,198),(36,73,631,632),(36,82,865,874),(36,83,877,879),(39,19,1376,1376),(36,53),(36,85),(39,3),(39,20)],'Autodualité de la Jacobienne, suivant Artin-Mazur.','There are 49 retained scans: cote36 53–85 and cote39 3–8,10–17,19–20. Pencil numbers are scan−1; reused printed numbers are separate. No manuscript-wide page total or date is written. Entry101 also contains the prior-project comparison matrix, whose backing files are not attached.','The number49 counts supplied scans, not a stated authorial extent. The prior-project links are leads and retained in a separate table; absence of direct bearing does not independently verify those projects.','agrees','The heading and numbering statements agree with all page markers; package-selection reports about omitted blank scans cannot be independently verified without images.')
add(475,[102],'Prior-run provenance and bibliography','other',[], '', 'The entry reports RETURNED statuses for LM4,LM7,LM7_PUSH, separates those from individual referee verdicts, and gives nine comparison references. These are earlier-run provenance/bibliographic statements, not manuscript mathematics.','Only the references actually reopened in this run receive verified bibliography flags. Unattached register and QA records are not independently certified.','not on the page','Retained with corrected evidentiary scope: reports about previous runs and their scans belong to provenance, not claims of Grothendieck.','corrected')
add(476,[103],'Limits of source identification and prior transcription audit','other',[], '', 'The entry states which printed parallels were identified, and reports the previous run’s hash, image-inspection, inventory and QA outcomes. It accurately limits complete identification of invariant-cycle variants and reused sources.','Those previous audit artifacts and scans are not in this run; their reported QA is carried as provenance, not re-performed or proof-certified. This run independently reads the frozen text and researches the mathematical parallels.','not on the page','Retained with corrected scope: exact bibliographic matches are rechecked independently; reported old image/QA work is not a new check event.','corrected')

def write():
 # Exact short excerpts replace typographical shorthand in the authored rows.
 exact={418:r'\underline Z/\ell\underline Z',426:r'{}_n\delta/{}_n\delta\prime',430:'des deg. des 0-cycles',432:'démonstration arithmétique',436:r'Mais les ${}_{\ell^\nu}S_i$',439:"quitte\nà agrandir $K$ en $K'$",440:r'\operatorname{Ker}u',443:"\\sum\\delta_i n_i n'_i",446:"l'obstruction",447:'$k$ anneau commutatif',454:"On veut qu'on ait une réciproque",459:"incorrect, 1 n'est pas nilp.!",464:"en car. 0 c'est équivalent",465:'canoniques, fonctorielles',469:r'\unsure{X\prime|X}'}
 exact[426]="{}_n\\delta/{}_n\\delta'"
 exact[469]="\\unsure{X'|X}"
 for i in items:
  n=int(i['id'].split('-')[-1])
  if n in exact:i['his_words']=exact[n]
  if i['his_words']:assert i['his_words'] in '\n'.join(src),(i['id'],i['his_words'])
 (OUT/'items.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
 with (OUT/'entries.tsv').open('w') as f:
  w=csv.DictWriter(f,fieldnames=['entry_id','item_id','verdict','reason'],delimiter='\t');w.writeheader();w.writerows(sorted(verdicts,key=lambda v:int(v['entry_id'].split('#')[-1])))
 seen=[int(v['entry_id'].split('#')[-1]) for v in verdicts]
 assert sorted(seen)==list(range(1,104)),set(range(1,104))-set(seen)
 print(f'Human-authored p4 core: {len(items)} items, {len(verdicts)} entry verdicts; exact entry coverage validated.')
if __name__=='__main__':write()
